<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {usePayrollPage} from '../payrollPage'
import {WorkforceApiError} from '../api'
import {chooseCompany,copy,validMoney} from '../payrollUi'
import {storeToday} from '../time'
import type {PayrollHomeData,BatchDetail,Payslip,Payment} from '../payrollTypes'
import PhaseStatus from '../components/PhaseStatus.vue'
const route=useRoute(),router=useRouter(),id=String(route.params.id),employeeId=String(route.query.employeeId||''),reverseId=String(route.query.reverse||''),paymentId=crypto.randomUUID(),{api,r,t,p,base,current,loading,busy,failure,notice,load,write}=usePayrollPage(),ready=ref(false),person=ref(''),remaining=ref(''),original=ref<Payment|null>(null),uncertain=ref(false),pending=ref<Record<string,unknown>|null>(null),draft=reactive({amount:'',paymentDate:storeToday(),method:'bank' as 'cash'|'bank'|'paynow'|'other',bank:'',reference:'',note:''})
function cents(v:string){const [a,b='']=v.split('.');return BigInt(a||0)*100n+BigInt(b.padEnd(2,'0').slice(0,2))}
onMounted(()=>void load(async()=>{const h=await api().get<PayrollHomeData>('/payroll-home');chooseCompany(h,'');if(h.employeeId===employeeId)throw new WorkforceApiError(403,'WORKFORCE_FORBIDDEN');const d=await api().get<BatchDetail>('/payroll-batches/'+id);chooseCompany(h,d.batch.companyId);if(d.batch.status!=='published'||!d.employees.some(e=>e.id===employeeId))throw new WorkforceApiError(403,'WORKFORCE_FORBIDDEN');const slip=await api().get<Payslip>('/payroll-batches/'+id+'/payslips/'+employeeId);let old:Payment|null=null;if(reverseId){old=d.payments.find(x=>x.id===reverseId&&x.employeeId===employeeId&&!x.reversesId)||null;if(!old||d.payments.some(x=>x.reversesId===reverseId))throw new WorkforceApiError(409,'WORKFORCE_PAYROLL_OVERPAYMENT')}return {d,slip,old}},v=>{person.value=v.d.employees.find(e=>e.id===employeeId)?.name||'';remaining.value=v.slip.remainingAmount;original.value=v.old;draft.amount=v.old?.amount||v.slip.remainingAmount;draft.method=v.old?.method||v.slip.payment?.method||'bank';draft.bank=v.old?.bank||v.slip.payment?.bank||'';ready.value=true}))
function save(){if(busy.value||uncertain.value||!ready.value)return;if(!validMoney(draft.amount)||cents(draft.amount)<=0n||(!reverseId&&cents(draft.amount)>cents(remaining.value))||!draft.paymentDate||(draft.method==='bank'&&!draft.reference.trim())||(draft.method==='bank'&&!original.value&&!draft.bank.trim())||!draft.note.trim()||draft.reference.length>100||draft.note.length>500){failure.value=r('invalid');return}pending.value={employeeId,amount:draft.amount,paymentDate:draft.paymentDate,method:draft.method,bank:draft.method==='cash'?'':draft.bank.trim(),reference:draft.reference.trim(),note:draft.note.trim(),reversesId:reverseId||null};recover()}
function recover(){if(busy.value||!pending.value)return;const body=copy(pending.value);void write(async()=>{try{await api().put('/payroll-batches/'+id+'/payments/'+paymentId,body);if(current()){uncertain.value=false;pending.value=null}}catch(e){if(current()){uncertain.value=!(e instanceof WorkforceApiError&&e.status>=400&&e.status<500);if(!uncertain.value)pending.value=null}throw e}},async()=>{if(current())await router.push(base.value+'/payroll-batches/'+id)})}
</script>
<template><section class="wf-panel wf-form-panel"><h2>{{r(reverseId?'reversal':'payment')}}</h2><PhaseStatus :failure="failure" :notice="notice" :loading="loading"/><form v-if="ready&&!loading" @submit.prevent="save"><p>{{person}} · {{r('remaining')}}: SGD {{remaining}}</p><p class="wf-hint">{{r(reverseId?'reversalHint':'paymentHint')}}</p><fieldset :disabled="busy||uncertain"><div class="wf-grid"><label>{{r('amount')}}<input v-model="draft.amount" required inputmode="decimal" :disabled="!!original"></label><label>{{r('paymentDate')}}<input v-model="draft.paymentDate" required type="date" :max="storeToday()"></label></div><label>{{r('method')}}<select v-model="draft.method" :disabled="!!original"><option value="cash">{{r('cash')}}</option><option value="bank">{{r('bank')}}</option><option value="paynow">{{r('paynow')}}</option><option value="other">{{r('other')}}</option></select></label><label v-if="draft.method!=='cash'">{{r('bankName')}}<input v-model="draft.bank" maxlength="100" :disabled="!!original" :required="draft.method==='bank'&&!original"></label><label>{{r('reference')}}<input v-model="draft.reference" :required="draft.method==='bank'" maxlength="100"></label><label>{{r('paymentNote')}}<textarea v-model="draft.note" required maxlength="500" rows="3"></textarea></label></fieldset><footer class="wf-form-actions"><RouterLink class="wf-button" :to="base+'/payroll-batches/'+id">{{t('cancel')}}</RouterLink><button v-if="!uncertain" class="primary" :disabled="busy">{{busy?t('saving'):t('save')}}</button><button v-else type="button" :disabled="busy" @click="recover">{{r('recover')}}</button></footer><p v-if="uncertain" class="wf-issue">{{r('recovery')}}</p></form></section></template>
